9. Currently taking any drug contraindicated with Losartan administration.","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"centralContacts":[{"name":"Amira Y Mohamed","role":"CONTACT","phone":"01020435341","email":"amira.yousry@pharma.asu.edu.eg"}],"overallOfficials":[{"name":"Amira Y mohamed","affiliation":"Ain Shams University","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"Hospital","status":"RECRUITING","city":"Cairo","country":"Egypt","geoPoint":{"lat":30.06263,"lon":31.24967}}]}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-09-28"},"conditionBrowseModule":{"meshes":[{"id":"D015179","term":"Colorectal Neoplasms"},{"id":"D013280","term":"Stomatitis"}],"ancestors":[{"id":"D007414","term":"Intestinal Neoplasms"},{"id":"D005770","term":"Gastrointestinal Neoplasms"},{"id":"D004067","term":"Digestive System Neoplasms"},{"id":"D009371","term":"Neoplasms by Site"},{"id":"D009369","term":"Neoplasms"},{"id":"D004066","term":"Digestive System Diseases"},{"id":"D005767","term":"Gastrointestinal Diseases"},{"id":"D003108","term":"Colonic Diseases"},{"id":"D007410","term":"Intestinal Diseases"},{"id":"D012002","term":"Rectal Diseases"},{"id":"D009059","term":"Mouth Diseases"},{"id":"D009057","term":"Stomatognathic Diseases"}]},"interventionBrowseModule":{"meshes":[{"id":"D019808","term":"Losartan"}],"ancestors":[{"id":"D001713","term":"Biphenyl Compounds"},{"id":"D001555","term":"Benzene Derivatives"},{"id":"D006841","term":"Hydrocarbons, Aromatic"},{"id":"D006844","term":"Hydrocarbons, Cyclic"},{"id":"D006838","term":"Hydrocarbons"},{"id":"D009930","term":"Organic Chemicals"},{"id":"D007093","term":"Imidazoles"},{"id":"D001393","term":"Azoles"},{"id":"D006573","term":"Heterocyclic Compounds, 1-Ring"},{"id":"D006571","term":"Heterocyclic Compounds"},{"id":"D013777","term":"Tetrazoles"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT01023633","orgStudyIdInfo":{"id":"Oxali04882"},"organization":{"fullName":"Nanjing Medical University","class":"OTHER"},"briefTitle":"OPTIMOX1 in Chinese mCRC Patients","officialTitle":"A Randomized Study Of Continuous FOLFOX4 vs. FOLFOX4 in a Stop-and-Go Fashion in 1st Line Advanced Colorectal Cancer"},"statusModule":{"statusVerifiedDate":"2009-12","overallStatus":"UNKNOWN","lastKnownStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2009-10"},"primaryCompletionDateStruct":{"date":"2014-01","type":"ESTIMATED"},"completionDateStruct":{"date":"2015-07","type":"ESTIMATED"},"studyFirstSubmitDate":"2009-12-01","studyFirstSubmitQcDate":"2009-12-01","studyFirstPostDateStruct":{"date":"2009-12-02","type":"ESTIMATED"},"lastUpdateSubmitDate":"2009-12-01","lastUpdatePostDateStruct":{"date":"2009-12-02","type":"ESTIMATED"}},"sponsorCollaboratorsModule":{"responsibleParty":{"oldNameTitle":"Nanjing Medical University.","oldOrganization":"Nanjing Medical University"},"leadSponsor":{"name":"Nanjing Medical University","class":"OTHER"}},"oversightModule":{"oversightHasDmc":true},"descriptionModule":{"briefSummary":"Previous OPTIMOX1 study investigated the use of oxaliplatin discontinuation and reintroduction in a novel stop-and-go strategy. Previously untreated patients were randomly assigned to either FOLFOX4 administered every 2 weeks until progression (arm A) or FOLFOX7 for 6 cycles, maintenance without oxaliplatin for 12 cycles, and reintroduction of FOLFOX7 for another 6 cycles (arm B). Data showed that there was no significant difference in median progression-free survival (PFS) and overall survival (OS) between two arms. Furthermore, this study showed lower Grade 3 neurotoxicity rate in arm B (17.9% vs 13.3%, P = 0.12).In order to investigate the efficacy and feasibility of the novel "Stop and go" strategy in Chinese mCRC patients, Prof. Shu Yongqian in JiangShu Province Hospital plans to conduct a randomized controlled study to compare continuous FOLFOX4 vs. FOLFOX4 in a Stop-and-Go Fashion in 1st Line mCRC patients. To avoid the high oxaliplatin dosage related neurotoxicity, FOLFOX4 regimen is chosen in this study."},"conditionsModule":{"conditions":["Colorectal Cancer"],"keywords":["to investigate the efficacy and feasibility of this novel treatment strategy in Chinese mCRC patients","Primary Endpoint:DDC","Secondary Endpoint:OS, RR,DCR, PFS,safety"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE4"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":300,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Arm A: FOLFOX 4 continuous (Oxaliplatin, LV, 5-FU)","type":"ACTIVE_COMPARATOR","description":"The arm A (FOLFOX4 continuous arm):receive FOLFOX4 every 2 weeks until progression or for maximum 24 cycles.","interventionNames":["Drug: Oxaliplatin, LV, 5-FU"]},{"label":"Arm B: FOLFOX4 Stop and go (Oxaliplatin, LV, 5-FU)","type":"EXPERIMENTAL","description":"The arm B will receive FOLFOX4 for 6 cycles, maintenance with 5FU/LV for 12 cycles, and reintroduction of FOLFOX4 for 6 cycles","interventionNames":["Drug: Oxaliplatin, LV, 5-FU"]}],"interventions":[{"type":"DRUG","name":"Oxaliplatin, LV, 5-FU","description":"Arm B(Intervention arm) will receive FOLFOX4 for 6 cycles, maintenance with 5FU/LV for 12 cycles, and reintroduction of FOLFOX4 for 6 cycles.

FOLFOX4 regimen:

OXA 85mg/m2 , 2 hour infusion, d1 , Leucovorin 200 mg/m2 plus 5-FU 400mg IV bolus, then continuous 22 hour 600 mg/m2 infusion on day 1 and 2 Q2W","armGroupLabels":["Arm A: FOLFOX 4 continuous (Oxaliplatin, LV, 5-FU)","Arm B: FOLFOX4 Stop and go (Oxaliplatin, LV, 5-FU)"],"otherNames":["Eloxatin"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"DDC: Duration of Disease Control","timeFrame":"Oct2012"}],"secondaryOutcomes":[{"measure":"OS, RR, PFS, DCR, safety,","timeFrame":"Oct 2015"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Patients with histologically confirmed adenocarcinoma of the colon or rectum
