{"protocolSection":{"identificationModule":{"nctId":"NCT01265433","nctIdAliases":["NCT01890980"],"orgStudyIdInfo":{"id":"10-134"},"organization":{"fullName":"Sellas Life Sciences Group","class":"INDUSTRY"},"briefTitle":"Galinpepimut-S (WT-1 Analog Peptide) Vaccine in Malignant Pleural Mesothelioma After Combined Modality Therapy","officialTitle":"Randomized Phase II Study of Adjuvant WT-1 Analog Peptide Vaccine in Patients With Malignant Pleural Mesothelioma (MPM) After Completion of Combined Modality Therapy"},"statusModule":{"statusVerifiedDate":"2024-10","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2010-12-21","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2016-11-30","type":"ACTUAL"},"completionDateStruct":{"date":"2017-07-25","type":"ACTUAL"},"studyFirstSubmitDate":"2010-12-21","studyFirstSubmitQcDate":"2010-12-22","studyFirstPostDateStruct":{"date":"2010-12-23","type":"ESTIMATED"},"resultsFirstSubmitDate":"2024-01-30","resultsFirstSubmitQcDate":"2024-10-01","resultsFirstPostDateStruct":{"date":"2024-10-09","type":"ACTUAL"},"lastUpdateSubmitDate":"2024-10-01","lastUpdatePostDateStruct":{"date":"2024-10-09","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Sellas Life Sciences Group","class":"INDUSTRY"},"collaborators":[{"name":"United States Department of Defense","class":"FED"}]},"oversightModule":{"oversightHasDmc":true},"descriptionModule":{"briefSummary":"Study of galinpepimut-S, a Wilms Tumor-1 (WT1) vaccine, to see if it delays or prevents the mesothelioma from growing back after surgery. WT1 is a protein in cancer cells that regulates gene expression and causes cell growth.","detailedDescription":"The doctors are testing galinpepimut-S, a Wilms Tumor-1 (WT1) vaccine, to see if it delays or prevents the mesothelioma from growing back after surgery. WT1 is a protein in cancer cells that regulates gene expression and causes cell growth. Mesothelioma tumors generally have high levels of WT1.This study was originally designed to have two treatment groups. One group received non-specific immunotherapy with medications called Montanide and Sargramostim (Granulocyte Macrophage Colony Stimulating Factor, GM-CSF). Enrollment to this group has stopped The other group, which continues receives more specific immunotherapy with galinpepimut-S plus Montanide and GM-CSF. Both Montanide and GM-CSF are commonly given along with vaccines because they have a general effect in boosting the immune response. Some researchers believe that this general increase in the immune system may have some effect in treating cancer. Some studies using GM-CSF with melanoma vaccines have suggested that it could lessen the effects of the vaccine. The addition of the WT1 proteins makes this therapy more directed to mesothelioma. The combination of galinpepimut-S with Montanide and GM-CSF has been tested in a prior trial including 9 patients with advanced mesothelioma. In that trial, the vaccine was safe and caused an immune response."},"conditionsModule":{"conditions":["Malignant Pleural Mesothelioma"],"keywords":["GM-CSF","MONTANIDE ISA 51","WT1 PEPTIDE SPECIFIC T CELLS","Vaccine","10-134","Galinpepimut-S"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE2"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"DOUBLE","whoMasked":["PARTICIPANT","INVESTIGATOR"]}},"enrollmentInfo":{"count":41,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Galinpepimut-S + Montanide + GM-CSF","type":"EXPERIMENTAL","description":"Galinpepimut-S emulsified with Montanide adjuvant (1:1 ratio) 1 mL and GM-CSF 70 mcg","interventionNames":["Biological: Galinpepimut-S + Montanide + GM-CSF"]},{"label":"Montanide + GM-CSF","type":"PLACEBO_COMPARATOR","description":"Montanide adjuvant 1 mL and GM-CSF 70 mcg","interventionNames":["Biological: Montanide + GM-CSF"]}],"interventions":[{"type":"BIOLOGICAL","name":"Galinpepimut-S + Montanide + GM-CSF","description":"Patients will receive 6 injections over 12 weeks. Treatment will be administered on weeks 0, 2, 4, 6, 8, and 10. All patients will receive Sargramostim (GM-CSF) (70 mcg) injected subcutaneously on days 0 and -2 of each vaccination. Patients may self administer the Sargramostim (GM-CSF) on day -2 if they have been appropriately instructed on SQ injection administration. Patients will be informed of the expected reactions such as irritation at the injection site. Patients will keep a logbook noting the time and placement of the injection. Patients will also receive 1.0 ml of emulsion with Montanide alone or with WT-1 peptides plus Montanide. It will be administered by a nurse (it may not be self administered) subcutaneously to the same anatomical site as the GM-CSF. This site will be marked by the patient or treating healthcare professional by a permanent marker pen.","armGroupLabels":["Galinpepimut-S + Montanide + GM-CSF"]},{"type":"BIOLOGICAL","name":"Montanide + GM-CSF","description":"Patients will receive 6 injections over 12 weeks. Treatment will be administered on weeks 0, 2, 4, 6, 8, and 10. All patients will receive Sargramostim (GM-CSF) (70 mcg) injected subcutaneously on days 0 and -2 of each vaccination. Patients may self administer the Sargramostim (GM-CSF) on day -2 if they have been appropriately instructed on SQ injection administration. Patients will be informed of the expected reactions such as irritation at the injection site. Patients will keep a logbook noting the time and placement of the injection. Patients will also receive 1.0 ml of emulsion with Montanide alone or with WT-1 peptides plus Montanide. It will be administered by a nurse (it may not be self-administered)subcutaneously to the same anatomical site as the GM-CSF. This site will be marked by the patient or treating healthcare professional by a permanent marker pen.","armGroupLabels":["Montanide + GM-CSF"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"1-year Progression-free Survival","description":"Progression free survival (PFS) rate will be calculated from the time of randomization to first evidence of disease recurrence or death of any cause.","timeFrame":"1 year"},{"measure":"Progression-free Survival","description":"Median progression free survival (PFS) is where PFS are assessed from the time of randomization to first evidence of disease recurrence or death of any cause.","timeFrame":"Up to 5 years and 11 months"}],"secondaryOutcomes":[{"measure":"Overall Survival","description":"Median overall survival (OS) is estimated from time of randomization to all cause mortality","timeFrame":"Uo to 5 years and 11 months"},{"measure":"Immune Response","description":"Immunogenicity of galinpepimut-S and control from a subset of participants","timeFrame":"12 weeks"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Pathologic diagnosis of malignant pleural mesothelioma (MPM) confirmed at participating institution.
* Positive immunohistochemical staining for WT-1 (greater than 10% of cells).
* Completion of multimodality therapy. This must include surgical resection by either pleurectomy/decortication or extrapleural pneumonectomy. The surgery should be performed with the intent of complete resection, though patients with an R1 resection will still be eligible. Patients should have also received treatment with chemotherapy and/or radiation. Patients with an R2 resection are also eligible as long as the site of residual disease is treated post-operatively with radiotherapy.
* 4-12 weeks since completion of combined modality therapy.
* Age \> or = to 18 years
* Karnofsky performance status \> or = to 70%
* Hematologic parameters: Absolute neutrophil count \> or = to 1000/mcL, Platelets \> or = to 50K/mcL.
* Biochemical parameters: Total bilirubin \< or = to 2.0 mg/dl, AST and ALT \< or = to 2.5 x upper limits of normal, Creatinine \< or = to 2.0 mg/dl.

Exclusion Criteria:

* Pregnant or lactating women.
* Patients with active infection requiring systemic antibiotics, antiviral, or antifungal treatments.
* Patients with a serious unstable medical illness or another active cancer.
* Patients taking systemic corticosteroids.
* Patients with an immunodeficiency syndrome.","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Marjorie Zauderer, MD","affiliation":"Memorial Sloan Kettering Cancer Center","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"Memorial Sloan Kettering Cancer Center","city":"New York","state":"New York","zip":"10065","country":"United States","geoPoint":{"lat":40.71427,"lon":-74.00597}}]},"referencesModule":{"references":[{"pmid":"28972039","type":"RESULT","citation":"Zauderer MG, Tsao AS, Dao T, Panageas K, Lai WV, Rimner A, Rusch VW, Adusumilli PS, Ginsberg MS, Gomez D, Rice D, Mehran R, Scheinberg DA, Krug LM. A Randomized Phase II Trial of Adjuvant Galinpepimut-S, WT-1 Analogue Peptide Vaccine, After Multimodality Therapy for Patients with Malignant Pleural Mesothelioma. Clin Cancer Res. 2017 Dec 15;23(24):7483-7489. doi: 10.1158/1078-0432.CCR-17-2169. Epub 2017 Sep 28."}],"seeAlsoLinks":[{"label":"Memorial Sloan Kettering Cancer Center","url":"http://www.mskcc.org/mskcc/html/44.cfm"}]},"ipdSharingStatementModule":{"ipdSharing":"NO"}},"resultsSection":{"participantFlowModule":{"groups":[{"id":"FG000","title":"Galinpepimut-S + Montanide + GM-CSF","description":"Patients will receive 6 injections over 12 weeks. Treatment will be administered on weeks 0, 2, 4, 6, 8, and 10. All patients will receive Sargramostim (GM-CSF) (70 mcg) injected subcutaneously on days 0 and -2 of each vaccination. Patients may self administer the Sargramostim (GM-CSF) on day -2 if they have been appropriately instructed on SQ injection administration. Patients will be informed of the expected reactions such as irritation at the injection site. Patients will keep a logbook noting the time and placement of the injection. Patients will also receive 1.0 ml of emulsion with Montanide alone or with WT-1 peptides plus Montanide. It will be administered by a nurse (it may not be self administered) subcutaneously to the same anatomical site as the GM-CSF. This site will be marked by the patient or treating healthcare professional by a permanent marker pen."},{"id":"FG001","title":"Montanide + GM-CSF","description":"Montanide adjuvant + GM-CSF: Patients will receive 6 injections over 12 weeks. Treatment will be administered on weeks 0, 2, 4, 6, 8, and 10. All patients will receive Sargramostim (GM-CSF) (70 mcg) injected subcutaneously on days 0 and -2 of each vaccination. Patients may self administer the Sargramostim (GM-CSF) on day -2 if they have been appropriately instructed on SQ injection administration. Patients will be informed of the expected reactions such as irritation at the injection site. Patients will keep a logbook noting the time and placement of the injection. Patients will also receive 1.0 ml of emulsion with Montanide alone or with WT-1 peptides plus Montanide. It will be administered by a nurse (it may not be self-administered)subcutaneously to the same anatomical site as the GM-CSF. This site will be marked by the patient or treating healthcare professional by a permanent marker pen."}],"periods":[{"title":"Overall Study","milestones":[{"type":"STARTED","achievements":[{"groupId":"FG000","numSubjects":"20"},{"groupId":"FG001","numSubjects":"21"}]},{"type":"COMPLETED","achievements":[{"groupId":"FG000","numSubjects":"20"},{"groupId":"FG001","numSubjects":"21"}]},{"type":"NOT COMPLETED","achievements":[{"groupId":"FG000","numSubjects":"0"},{"groupId":"FG001","numSubjects":"0"}]}]}]},"baselineCharacteristicsModule":{"groups":[{"id":"BG000","title":"Galinpepimut-S","description":"Galinpepimut-s + Montanide + GM-CSF"},{"id":"BG001","title":"Control","description":"Montanide + GM-CSF"},{"id":"BG002","title":"Total","description":"Total of all reporting groups"}],"denoms":[{"units":"Participants","counts":[{"groupId":"BG000","value":"20"},{"groupId":"BG001","value":"21"},{"groupId":"BG002","value":"41"}]}],"measures":[{"title":"Age, Cont