{"protocolSection":{"identificationModule":{"nctId":"NCT03532347","orgStudyIdInfo":{"id":"8090"},"organization":{"fullName":"Newcastle-upon-Tyne Hospitals NHS Trust","class":"OTHER"},"briefTitle":"Endoscopic Ultrasound Guided Tissue Sampling (The SharkBITE Study)","officialTitle":"SharkCore Biopsy Needle Versus Standard FNA Needle in the Diagnosis of Solid Pancreatic Masses a Randomised Controlled Cross-over Trial of EUS Guided Tissue Acquisition - The SharkBITE Study","acronym":"SharkBITE"},"statusModule":{"statusVerifiedDate":"2019-06","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2017-05-22","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2018-05-04","type":"ACTUAL"},"completionDateStruct":{"date":"2018-11-04","type":"ACTUAL"},"studyFirstSubmitDate":"2017-11-01","studyFirstSubmitQcDate":"2018-05-09","studyFirstPostDateStruct":{"date":"2018-05-22","type":"ACTUAL"},"lastUpdateSubmitDate":"2019-06-07","lastUpdatePostDateStruct":{"date":"2019-06-10","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Newcastle-upon-Tyne Hospitals NHS Trust","class":"OTHER"},"collaborators":[{"name":"Medtronic","class":"INDUSTRY"}]},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false,"isUsExport":false},"descriptionModule":{"briefSummary":"This study compares the diagnostic performance of Endoscopic ultrasound (EUS) guided fine needle aspiration and EUS guided core biopsy (SharkCore) in patients with a solid pancreatic mass.","detailedDescription":"Endoscopic ultrasound (EUS) guided fine needle aspiration (FNA) and fine needle biopsy (FNB) are the standard methods for obtaining tissue samples from tumours of the pancreas. The diagnostic accuracy by strict criteria is around 75-80%. A non diagnostic sample causes delay and the need for a repeat procedure. To date no significant difference has been found between standard FNA and standard FNB needles. A novel opposing bevel design (SharkCore) needle for FNB may provide better diagnostic performance. The aim of this study is to compare the performance of a standard needle and the Sharkcore needle. Patients attending for routine biopsy of a suspected pancreatic tumour will be invited to participate. All participants will have 3 samples taken with each needle. The samples from each needle will be processed and reported separately with the pathologists blinded as to the report from the other needle. Following the procedure participants will be observed as normal in the recovery area and allowed home later. Further study participation is limited to 1 telephone call at 7 days. Participants will be asked if they have developed any new symptoms since the procedure and whether they have had to seek medical attention for this.The risks of the study procedure are the same as those of a non study procedure. Both needle types are in routine use in our unit. The study will be performed in the endoscopy unit of the Freeman hospital. The study is funded by a grant from Medtronic the company who make the Sharkcore needle. The study is planned to recruit 108 participants over 10 months with a further 6 months of follow up. If the new needle is found to perform better its routine use will potentially reduce the delay experienced by patients as well as the cost incurred by repeat procedures."},"conditionsModule":{"conditions":["Pancreas Cancer","Pancreas Neoplasm, Benign","Chronic Pancreatitis","Pancreas Adenocarcinoma"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"NA","interventionModel":"SINGLE_GROUP","interventionModelDescription":"All participants will receive both interventions the order i.e. FNB first or FNA first will be randomised. The pathologists reporting the samples will be blinded to the results with the alternative device","primaryPurpose":"DIAGNOSTIC","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":108,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"EUS tissue sampling","type":"EXPERIMENTAL","description":"Device: EUS-FNA needle (Beacon) 3 passes 25g needle from head of pancreas; 22g needle from neck, body and tail

Device:EUS-FNB needle (Beacon Sharkcore) 3 passes 25g needle from head of pancreas; 22g needle from neck, body and tail","interventionNames":["Device: EUS-FNA needle (Beacon)"]}],"interventions":[{"type":"DEVICE","name":"EUS-FNA needle (Beacon)","description":"Participants will be randomised to an initial 3 passes with Beacon FNA and then Beacon SharkCore biopsy needles or vice versa. 25g needles will be used for trans duodenal puncture and 22g for trans gastric puncture.","armGroupLabels":["EUS tissue sampling"],"otherNames":["EUS-FNB needle (Beacon SharkCore)"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"The sensitivity of standard Beacon FNA needle compared with the SharkCore (FNB) core biopsy needle in the sampling of solid pancreatic mass lesions.","description":"The sensitivity of standard Beacon FNA needle compared with the SharkCore (FNB) core biopsy needle in the sampling of solid pancreatic mass lesions during the EUS procedure.","timeFrame":"During EUS procedure"}],"secondaryOutcomes":[{"measure":"To compare the adequacy of the sample obtained with standard Beacon FNA needle compared with the SharkCore core biopsy needle in the sampling of solid pancreatic mass lesions.","description":"To compare the adequacy of the sample obtained with standard Beacon FNA needle compared with the SharkCore core biopsy needle in the sampling of solid pancreatic mass lesions during EUS procedure per patient","timeFrame":"During EUS Procedure"},{"measure":"Duration of pathologist reporting time","description":"During pathologist diagnostic routine reporting period per sample standard is usually 1-2 weeks","timeFrame":"Per sample anticipated to be 1-2 weeks"},{"measure":"Cost benefit analysis of the needle types","description":"An analysis to assess which needle is the most cost-effective","timeFrame":"Over study period which is anticipated to be around 1 year"},{"measure":"Duration of sampling procedures","description":"Duration of sampling procedures during EUS procedure per patient","timeFrame":"During the EUS procedure"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Adult patients 18 years and above with a solid pancreatic mass of any size, needing to Undergo the EUS examination to collect sample for diagnosis will be recruited for the study. The definition of a solid pancreatic mass will be based on an ultrasound or a CT scan result or based on the findings of a EUS examination done prior.
* Patients should have the ability and be willing to give informed consent

Exclusion Criteria:

* Cysts that do not have a significant solid component will be excluded
* Any contraindication to pancreatic biopsy.","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Kofi Oppong, Dr","affiliation":"Consultant Gastroenterologist","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"The Newcastle upon Tyne Hospitals NHS Foundation Trust","city":"Newcastle","state":"Newcastle Upon Tyne","zip":"NE7 7DN","country":"United Kingdom","geoPoint":{"lat":54.21804,"lon":-5.88979}}]},"ipdSharingStatementModule":{"ipdSharing":"UNDECIDED"}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-09-28"},"conditionBrowseModule":{"meshes":[{"id":"D010190","term":"Pancreatic Neoplasms"},{"id":"D050500","term":"Pancreatitis, Chronic"}],"ancestors":[{"id":"D004067","term":"Digestive System Neoplasms"},{"id":"D009371","term":"Neoplasms by Site"},{"id":"D009369","term":"Neoplasms"},{"id":"D004701","term":"Endocrine Gland Neoplasms"},{"id":"D004066","term":"Digestive System Diseases"},{"id":"D010182","term":"Pancreatic Diseases"},{"id":"D004700","term":"Endocrine System Diseases"},{"id":"D010195","term":"Pancreatitis"},{"id":"D002908","term":"Chronic Disease"},{"id":"D020969","term":"Disease Attributes"},{"id":"D010335","term":"Pathologic Processes"},{"id":"D013568","term":"Pathological Conditions, Signs and Symptoms"}]}},"hasResults":false},
