{"protocolSection":{"identificationModule":{"nctId":"NCT03992378","orgStudyIdInfo":{"id":"9227"},"organization":{"fullName":"University of Oklahoma","class":"OTHER"},"briefTitle":"Neuromodulation to Regulate Inflammation and Autonomic Imbalance in Sepsis","officialTitle":"Neuromodulation to Regulate Inflammation and Autonomic Imbalance in Sepsis","acronym":"NERINASEPSIS"},"statusModule":{"statusVerifiedDate":"2026-03","overallStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2019-10-10","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2027-06","type":"ESTIMATED"},"completionDateStruct":{"date":"2027-12","type":"ESTIMATED"},"studyFirstSubmitDate":"2019-06-05","studyFirstSubmitQcDate":"2019-06-18","studyFirstPostDateStruct":{"date":"2019-06-20","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-03-26","lastUpdatePostDateStruct":{"date":"2026-04-01","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"University of Oklahoma","class":"OTHER"},"collaborators":[{"name":"Oklahoma City VA Medical Center","class":"FED"}]},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":true,"isUsExport":true},"descriptionModule":{"briefSummary":"Sepsis is life-threatening organ dysfunction caused by a dysregulated host response to infection. It is the most expensive healthcare condition to treat in United States and has a mortality rate of nearly 30%. It is widely known that exaggerated inflammation and imbalance between sympathetic and parasympathetic arms of the autonomic nervous system (ANS) contribute to progression and adverse outcomes in sepsis. The role of unchecked inflammation and unregulated ANS as a potential treatment target is an important gap in our knowledge that should be explored.

Cholinergic anti-inflammatory pathway (CAP) is an intricate network where the ANS senses inflammation by vagus nerve afferents and tries to regulate it by vagus nerve efferents to the reticuloendothelial system. The central hypothesis of this pilot clinical trial is that transcutaneous vagus nerve stimulation (TVNS) at tragus of the external ear can activate the CAP to suppress inflammation and improve autonomic imbalance as measured by inflammatory cytokine levels and heart rate variability (HRV) analysis. The investigators plan to randomize patients with septic shock into active and sham stimulation groups and study the effects of vagal stimulation on inflammatory cytokines, HRV and a clinical severity score of sepsis. Both groups will continue to receive the standard of care treatment for sepsis irrespective of group assignments. The investigators hypothesize that 4 hours of TVNS will suppress inflammatory markers and improve the balance between sympathetic and parasympathetic arms of ANS as measured by HRV, resulting in improved Sequential Organ Failure Assessment Score (SOFA). The preliminary data generated from this pilot study will lay the foundation for a larger clinical trial."},"conditionsModule":{"conditions":["Septic Shock"],"keywords":["Sepsis"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","interventionModelDescription":"Randomized controlled trial","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"DOUBLE","maskingDescription":"Double blind","whoMasked":["PARTICIPANT","OUTCOMES_ASSESSOR"]}},"enrollmentInfo":{"count":34,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Active Treatment","type":"EXPERIMENTAL","description":"Patients will receive a single 4-hour session of active transcutaneous vagus nerve stimulation.","interventionNames":["Device: Low Level Transcutaneous Vagus Nerve Stimulation"]},{"label":"Sham Control","type":"SHAM_COMPARATOR","description":"Patients will receive a single 4-hour session of sham transcutaneous vagus nerve stimulation.","interventionNames":["Device: Low Level Transcutaneous Vagus Nerve Stimulation"]}],"interventions":[{"type":"DEVICE","name":"Low Level Transcutaneous Vagus Nerve Stimulation","description":"Stimulation of the auricular branch of the vagus nerve at tragus of the external ear delivered by Parasym device.","armGroupLabels":["Active Treatment"]},{"type":"DEVICE","name":"Low Level Transcutaneous Vagus Nerve Stimulation","description":"Stimulation of the ear lobe delivered by Parasym device.","armGroupLabels":["Sham Control"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Change in Inflammatory Cytokine Tumor Necrosis Factor Alpha","description":"Serum inflammatory cytokine","timeFrame":"Baseline to 4 hours and baseline to 24 hours post stimulation"}],"secondaryOutcomes":[{"measure":"Change in Heart Rate Variability","description":"Time domain and frequency domain measures of heart rate variability","timeFrame":"Baseline to 4 hours post stimulation"},{"measure":"Change in Sequential Organ Failure Assessment Score","description":"Sequential Organ Failure Assessment Score calculation","timeFrame":"Baseline to 24 hours post stimulation"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

